import React from "react";
import { Col, Row, Toast } from "react-bootstrap";

const ProjToast = (props) => {
  const TypeText = ({ type }) => {
    switch (type) {
      case "create":
        return (
          <>
            <Toast.Header>
              <img
                className="rounded me-2"
                alt=""
              />
              <strong className="me-auto" style={{ fontSize: "1rem" }}>
                프로젝트 등록 성공
              </strong>
            </Toast.Header>
            <Toast.Body style={{ fontSize: "1rem" }}>
              새로운 프로젝트가 성공적으로 등록되었습니다.
            </Toast.Body>
          </>
        );
      case "update":
        return (
          <>
            <Toast.Header>
              <img
                className="rounded me-2"
                alt=""
              />
              <strong className="me-auto" style={{ fontSize: "1rem" }}>
                프로젝트 수정 성공
              </strong>
            </Toast.Header>
            <Toast.Body style={{ fontSize: "1rem" }}>
              프로젝트가 성공적으로 수정되었습니다.
            </Toast.Body>
          </>
        );
      default:
        return null;
    }
  };

  return (
    <Row>
      <Col md={6} className="mb-2">
        <Toast
          show={props.showA}
          onClose={props.toggleShowA}
          style={{
            width: "25rem",
            position: "fixed",
            bottom: "3em",
            right: "3em",
            zIndex: 105,
          }}
        >
          <TypeText type={props.type} />
        </Toast>
      </Col>
    </Row>
  );
};

export default ProjToast;
